void Bitmap816::Draw(int sx, int sy, int sw, int sh, unsigned short* dst,
                     int dx, int dy, int dw, int dh, int dpitch,
                     bool tblit) const
{
    if (dx < 0) {
        sx -= dx;
        sw += dx;
        dx = 0;
    }
    if (dy < 0) {
        sy -= dy;
        sh += dy;
        dy = 0;
    }
    if (dx + sw > dw)
        sw = dw - dx;
    if (dy + sh > dh)
        sh = dh - dy;

    if (sw > 0 && sh > 0) {
        unsigned char* src = map + sy * Pitch + sx;
        dst = static_cast<unsigned short*>(static_cast<void*>(
            static_cast<unsigned char*>(static_cast<void*>(dst))
            + dy * dpitch + dx * 2));
        if (tblit) {
            for (int y = 0; y < sh; ++y) {
                unsigned short* out = dst;
                unsigned char* in = src;
                for (int x = 0; x < sw; ++x) {
                    unsigned char pixel = *in++;
                    if (pixel)
                        *out = p16.data[pixel];
                    ++out;
                }
                dst = static_cast<unsigned short*>(static_cast<void*>(
                    static_cast<unsigned char*>(static_cast<void*>(dst))
                    + dpitch));
                src += Pitch;
            }
        } else {
            for (int y = 0; y < sh; ++y) {
                unsigned short* out = dst;
                unsigned char* in = src;
                for (int x = 0; x < sw; ++x) {
                    *out++ = p16.data[*in++];
                }
                dst = static_cast<unsigned short*>(static_cast<void*>(
                    static_cast<unsigned char*>(static_cast<void*>(dst))
                    + dpitch));
                src += Pitch;
            }
        }
    }
}

